<template><div class="telemetry"><header class="hero"><div><span class="eyebrow">FLIGHT TELEMETRY / REAL-TIME</span><h2>火箭实时状态监测</h2><p>{{sourceLabel}} · {{connected?'数据链路正常':'已暂停'}} · 更新周期 1 秒</p></div><div><el-tag :type="external?'success':'info'">{{external?'外部遥测':'仿真遥测'}}</el-tag><el-button size="small" @click="toggle">{{connected?'暂停刷新':'继续刷新'}}</el-button></div></header><div class="metrics"><el-card v-for="m in metrics" :key="m.label" shadow="never"><div class="metric-head"><span>{{m.label}}</span><el-tag size="small" type="success">{{m.status}}</el-tag></div><strong>{{m.value}}</strong><small>{{m.unit}}</small><div class="spark"><i v-for="(v,i) in m.history" :key="i" :style="{height:(v*100)+'%'}"/></div></el-card></div><div class="columns"><el-card shadow="never"><template #header><b>遥测趋势</b></template><div class="chart"><div v-for="(v,i) in trend" :key="i" class="point" :style="{height:(v*100)+'%'}"/></div><div class="legend"><span>推进压力</span><span>发动机温度</span><span>姿态误差</span></div></el-card><el-card shadow="never"><template #header><b>实时告警</b></template><el-empty v-if="!alarms.length" description="当前无告警"/><el-alert v-for="a in alarms" :key="a.time" :title="a.title" :description="a.detail" :type="a.type" show-icon :closable="false"/></el-card></div><el-card shadow="never" class="table"><template #header><b>最新遥测数据</b></template><el-table :data="rows" stripe><el-table-column prop="time" label="时间"/><el-table-column prop="pressure" label="推进压力(MPa)"/><el-table-column prop="temperature" label="发动机温度(℃)"/><el-table-column prop="attitude" label="姿态误差(°)"/><el-table-column prop="fuel" label="燃料余量(%)"/><el-table-column prop="source" label="来源"/></el-table></el-card></div></template>
<script setup>import{ref,computed,onMounted,onUnmounted}from'vue';const connected=ref(true),external=ref(false),rows=ref([]),trend=ref([]),tick=ref(0),timer=ref(null),sourceLabel=computed(()=>external.value?'外部遥测注入':'仿真遥测流'),metrics=ref([{label:'推进压力',value:'7.82',unit:'MPa',status:'正常',history:[.7,.75,.72,.8,.78,.82]},{label:'发动机温度',value:'642',unit:'℃',status:'正常',history:[.5,.55,.6,.62,.63,.64]},{label:'姿态误差',value:'0.018',unit:'°',status:'稳定',history:[.2,.18,.22,.19,.2,.18]},{label:'燃料余量',value:'68.4',unit:'%',status:'充足',history:[.9,.84,.8,.76,.72,.68]}]),alarms=ref([]);async function refresh(){tick.value++;let d=null;try{const r=await fetch('/api/v1/phm/telemetry/latest/');const j=await r.json();if(j.available)d=j.data}catch{}const t=new Date().toLocaleTimeString('zh-CN',{hour12:false});const p=d?Number(d.pressure).toFixed(2):(7.7+Math.sin(tick.value/3)*.2).toFixed(2),temp=d?Math.round(d.temperature):Math.round(640+Math.sin(tick.value/4)*8),att=d?Number(d.attitude).toFixed(3):(0.018+Math.abs(Math.sin(tick.value/5))*.006).toFixed(3),fuel=d?Number(d.fuel).toFixed(1):(68.4-tick.value*.01).toFixed(1);external.value=!!d;rows.value.unshift({time:t,pressure:p,temperature:temp,attitude:att,fuel,source:d?'外部':'仿真'});rows.value=rows.value.slice(0,8);trend.value=Array.from({length:18},(_,i)=>.55+Math.sin((i+tick.value)/3)*.18+.1);metrics.value[0].value=p;metrics.value[1].value=String(temp);metrics.value[2].value=att;metrics.value[3].value=fuel;alarms.value=Number(p)<7.55?[{time:t,title:'推进压力偏低',detail:`动力系统压力 ${p} MPa，来源：${d?'外部遥测':'仿真遥测'}`,type:'warning'}]:[]}function toggle(){connected.value=!connected.value}onMounted(()=>{refresh();timer.value=setInterval(()=>{if(connected.value)refresh()},1000)});onUnmounted(()=>clearInterval(timer.value))</script>
<style scoped>.telemetry{padding:24px;max-width:1400px}.hero{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px}.hero h2{margin:8px 0}.hero p{color:#718198}.hero .el-button{margin-left:12px}.eyebrow{color:#1777e8;font-size:12px;letter-spacing:1px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.metric-head{display:flex;justify-content:space-between;color:#61738b}.metrics strong{display:inline-block;font-size:28px;margin-top:14px;margin-right:8px}.metrics small{color:#8391a5}.spark{height:35px;display:flex;align-items:flex-end;gap:4px;margin-top:12px}.spark i{flex:1;background:#2b8be8;border-radius:2px 2px 0 0}.columns{display:grid;grid-template-columns:1.4fr 1fr;gap:16px;margin-top:16px}.chart{height:230px;display:flex;align-items:flex-end;gap:8px;padding:20px;border-bottom:1px solid #dfe6ef}.point{flex:1;background:linear-gradient(#2589ee,#20b7ae);border-radius:3px 3px 0 0}.legend{display:flex;gap:20px;padding-top:12px;color:#6e8096;font-size:13px}.table{margin-top:16px}.el-alert{margin-bottom:10px}@media(max-width:900px){.metrics{grid-template-columns:repeat(2,1fr)}.columns{grid-template-columns:1fr}}@media(max-width:560px){.metrics{grid-template-columns:1fr}.hero{display:block}}</style>
